#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

#define MAX_PDF_SIZE 65536
#define MAX_FIELD_LEN 512
#define AUDIT_LOG_PATH "/var/log/pdfgen/audit.log"

typedef struct {
    char *buffer;
    size_t offset;
    size_t capacity;
} PDFContext;

typedef struct {
    char username[MAX_FIELD_LEN];
    char document_title[MAX_FIELD_LEN];
    char metadata_author[MAX_FIELD_LEN];
    int include_javascript;
} PDFRequest;

static void audit_log(const char *action, const char *username, const char *detail) {
    FILE *f = fopen(AUDIT_LOG_PATH, "a");
    if (!f) return;
    time_t now = time(NULL);
    char timebuf[64];
    strftime(timebuf, sizeof(timebuf), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(f, "[%s] action=%s user=%s detail=%s\n", timebuf, action, username, detail);
    fclose(f);
}

static int pdf_ctx_init(PDFContext *ctx) {
    ctx->buffer = (char *)malloc(MAX_PDF_SIZE);
    if (!ctx->buffer) return -1;
    ctx->offset = 0;
    ctx->capacity = MAX_PDF_SIZE;
    return 0;
}

static void pdf_ctx_free(PDFContext *ctx) {
    free(ctx->buffer);
    ctx->buffer = NULL;
}

static int pdf_write(PDFContext *ctx, const char *data, size_t len) {
    if (ctx->offset + len > ctx->capacity) return -1;
    memcpy(ctx->buffer + ctx->offset, data, len);
    ctx->offset += len;
    return 0;
}

static int pdf_write_str(PDFContext *ctx, const char *str) {
    return pdf_write(ctx, str, strlen(str));
}

/* Sanitize PDF string by escaping parentheses and backslashes */
static int sanitize_pdf_string(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    for (; input[i] && j < outlen - 2; i++) {
        if (input[i] == '(' || input[i] == ')' || input[i] == '\\') {
            output[j++] = '\\';
            if (j >= outlen - 1) break;
        }
        output[j++] = input[i];
    }
    output[j] = '\0';
    return 0;
}

/* Sanitize for JavaScript context within PDF - removes script-dangerous chars */
static int sanitize_js_value(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    for (; input[i] && j < outlen - 2; i++) {
        char c = input[i];
        /* Allow alphanumeric, spaces, and basic punctuation */
        if (isalnum((unsigned char)c) || c == ' ' || c == '.' || 
            c == '-' || c == '_' || c == '@') {
            output[j++] = c;
        }
    }
    output[j] = '\0';
    return 0;
}

/* Sanitize for JavaScript string literal in HTML script context */
static int sanitize_js_string_literal(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    for (; input[i] && j < outlen - 7; i++) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c) || c == ' ' || c == '.' || c == '-' || c == '_' || c == '@') {
            output[j++] = c;
        } else {
            /* Hex-encode anything else for JS string safety */
            int written = snprintf(output + j, outlen - j, "\\x%02x", c);
            if (written > 0) j += written;
        }
    }
    output[j] = '\0';
    return 0;
}

/* Generate HTML preview that embeds PDF metadata for browser rendering */
static int generate_html_preview(const PDFRequest *req, char *html_out, size_t html_size) {
    char safe_title_html[MAX_FIELD_LEN * 2];
    char safe_author_html[MAX_FIELD_LEN * 2];
    char safe_title_js[MAX_FIELD_LEN * 4];
    char safe_author_js[MAX_FIELD_LEN * 4];

    /* Sanitize for HTML context */
    size_t i, j;
    j = 0;
    for (i = 0; req->document_title[i] && j < sizeof(safe_title_html) - 7; i++) {
        switch (req->document_title[i]) {
            case '<': memcpy(safe_title_html + j, "&lt;", 4); j += 4; break;
            case '>': memcpy(safe_title_html + j, "&gt;", 4); j += 4; break;
            case '&': memcpy(safe_title_html + j, "&amp;", 5); j += 5; break;
            case '"': memcpy(safe_title_html + j, "&quot;", 6); j += 6; break;
            case '\'': memcpy(safe_title_html + j, "&#x27;", 5); j += 5; break;
            default: safe_title_html[j++] = req->document_title[i]; break;
        }
    }
    safe_title_html[j] = '\0';

    j = 0;
    for (i = 0; req->metadata_author[i] && j < sizeof(safe_author_html) - 7; i++) {
        switch (req->metadata_author[i]) {
            case '<': memcpy(safe_author_html + j, "&lt;", 4); j += 4; break;
            case '>': memcpy(safe_author_html + j, "&gt;", 4); j += 4; break;
            case '&': memcpy(safe_author_html + j, "&amp;", 5); j += 5; break;
            case '"': memcpy(safe_author_html + j, "&quot;", 6); j += 6; break;
            case '\'': memcpy(safe_author_html + j, "&#x27;", 5); j += 5; break;
            default: safe_author_html[j++] = req->metadata_author[i]; break;
        }
    }
    safe_author_html[j] = '\0';

    /* Separately sanitize for JavaScript string literal context */
    sanitize_js_string_literal(req->document_title, safe_title_js, sizeof(safe_title_js));
    sanitize_js_string_literal(req->metadata_author, safe_author_js, sizeof(safe_author_js));

    snprintf(html_out, html_size,
        "<!DOCTYPE html>\n<html><head><title>%s</title></head>\n"
        "<body>\n<h1>PDF Preview</h1>\n"
        "<div id='metadata'>\n"
        "  <span class='title'>%s</span>\n"
        "  <span class='author'>%s</span>\n"
        "</div>\n"
        "<script>\n"
        "  var docMeta = {title: '%s', author: '%s'};\n"
        "  document.getElementById('metadata').setAttribute('data-info', JSON.stringify(docMeta));\n"
        "</script>\n"
        "</body></html>",
        safe_title_html, safe_title_html, safe_author_html,
        safe_title_js, safe_author_js);

    return 0;
}

static int generate_pdf(const PDFRequest *req, PDFContext *ctx) {
    char safe_str[MAX_FIELD_LEN * 2];
    char safe_author[MAX_FIELD_LEN * 2];

    audit_log("pdf_generate_start", req->username, req->document_title);

    pdf_write_str(ctx, "%PDF-1.4\n");
    pdf_write_str(ctx, "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
    pdf_write_str(ctx, "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n");
    pdf_write_str(ctx, "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] ");
    pdf_write_str(ctx, "/Contents 4 0 R >>\nendobj\n");

    /* Write document info with sanitized strings */
    sanitize_pdf_string(req->document_title, safe_str, sizeof(safe_str));
    sanitize_pdf_string(req->metadata_author, safe_author, sizeof(safe_author));
    char info_obj[2048];
    snprintf(info_obj, sizeof(info_obj),
        "5 0 obj\n<< /Title (%s) /Author (%s) >>\nendobj\n",
        safe_str, safe_author);
    pdf_write_str(ctx, info_obj);

    if (req->include_javascript) {
        char js_safe[MAX_FIELD_LEN];
        sanitize_js_value(req->document_title, js_safe, sizeof(js_safe));
        char js_obj[2048];
        snprintf(js_obj, sizeof(js_obj),
            "6 0 obj\n<< /Type /Action /S /JavaScript "
            "/JS (app.alert('Document: %s');) >>\nendobj\n", js_safe);
        pdf_write_str(ctx, js_obj);
    }

    pdf_write_str(ctx, "%%EOF\n");

    audit_log("pdf_generate_complete", req->username, "success");
    return 0;
}

int process_pdf_request(const char *username, const char *title, 
                        const char *author, int with_js,
                        char *pdf_out, size_t *pdf_len,
                        char *html_preview, size_t html_len) {
    PDFRequest req;
    PDFContext ctx;

    /* Validate required input pointers to prevent NULL-pointer dereference */
    if (!username || !title || !author || !pdf_out || !pdf_len) {
        return -1;
    }

    memset(&req, 0, sizeof(req));
    strncpy(req.username, username, MAX_FIELD_LEN - 1);
    strncpy(req.document_title, title, MAX_FIELD_LEN - 1);
    strncpy(req.metadata_author, author, MAX_FIELD_LEN - 1);
    req.include_javascript = with_js;

    audit_log("request_received", req.username, req.document_title);

    if (pdf_ctx_init(&ctx) != 0) return -1;

    if (generate_pdf(&req, &ctx) != 0) {
        pdf_ctx_free(&ctx);
        return -1;
    }

    if (ctx.offset <= *pdf_len) {
        memcpy(pdf_out, ctx.buffer, ctx.offset);
        *pdf_len = ctx.offset;
    }
    pdf_ctx_free(&ctx);

    /* Generate HTML preview for web UI */
    if (html_preview && html_len > 0) {
        generate_html_preview(&req, html_preview, html_len);
    }

    return 0;
}
